#include <ranges>
#include <vector>

std::vector<int> evenSquares(const std::vector<int>& values)
{
    std::vector<int> result{};
    for (int x : values
        | std::views::filter([](int n) { return n % 2 == 0; })
        | std::views::transform([](int n) { return n * n; }))
    {
        result.push_back(x);
    }
    return result;
}

unitTests:
TEST("filters then squares") { CHECK_EQ(evenSquares({ 1, 2, 3, 4, 5, 6 }), (std::vector<int>{ 4, 16, 36 })); }
TEST("negatives and zero") { CHECK_EQ(evenSquares({ -4, 0, 7 }), (std::vector<int>{ 16, 0 })); }
TEST("nothing even") { CHECK(evenSquares({ 1, 3 }).empty()); }

